export const offsetAccountDefinitions={offsetAccount:{title:'Compare an offset interest base with a complete alternative cost',fields:[
 ['offsetDebt','Gross loan principal held constant (CAD)',300000,0,1000000,25000],
 ['offsetCashBalance','Same cash held in offset or separate savings (CAD)',40000,0,1000000,10000],
 ['offsetQuote','Offset loan: annual simple interest assumption (%)',6,0,12,.25],
 ['offsetAlternative','Alternative loan: annual simple interest assumption (%)',5.5,0,12,.25],
 ['offsetSaving','Separate savings: annual simple gross interest assumption (%)',3,0,8,.25],
 ['offsetDays','Complete actual days in this constant-balance comparison',30,1,365,1],
 ['offsetFee','Extra offset fee for the entire selected period (CAD)',10,0,2000,10]
]}};
export function offsetAccountCosts(i,cash=i.offsetCashBalance,offsetRate=i.offsetQuote,alternativeRate=i.offsetAlternative){
 const fraction=i.offsetDays/365,eligible=Math.min(i.offsetDebt,cash),interestBase=Math.max(0,i.offsetDebt-cash);
 const offsetInterest=interestBase*offsetRate/100*fraction,alternativeInterest=i.offsetDebt*alternativeRate/100*fraction,separateInterest=cash*i.offsetSaving/100*fraction;
 const avoided=eligible*offsetRate/100*fraction,quotePremium=i.offsetDebt*(offsetRate-alternativeRate)/100*fraction;
 const offsetCost=offsetInterest+i.offsetFee,alternativeNetCost=alternativeInterest-separateInterest,advantage=alternativeNetCost-offsetCost;
 return {eligible,interestBase,offsetInterest,alternativeInterest,separateInterest,avoided,quotePremium,offsetCost,alternativeNetCost,advantage};
}
export function offsetAccountResult(kind,i){
 if(kind!=='offsetAccount')throw Error('Unknown offset-account topic.');
 const p=offsetAccountCosts(i),maxCash=Math.max(10000,i.offsetDebt*1.5,i.offsetCashBalance);
 const cashValues=[...new Set([0,i.offsetDebt,i.offsetCashBalance,maxCash,...Array.from({length:101},(_,j)=>j*maxCash/100)])].sort((a,b)=>a-b);
 return {metrics:[['Loan balance charged interest in the offset example',p.interestBase,'money'],['Interest avoided relative to the same offset-loan quote',p.avoided,'money'],['Net period cost advantage of offset after the extra fee',p.advantage,'money']],note:'Original hypothetical one-period cost comparison, using identical opening debt and cash. The full-offset example keeps cash in a separate linked account, pays no interest on any linked cash, and charges loan interest on max(gross principal − linked cash, 0). Cash above the loan amount cannot produce negative loan interest. The alternative keeps the full loan interest base and earns the entered gross savings interest on the same cash. Loan quotes may differ. All rates are independently entered annual SIMPLE assumptions on actual days / fixed 365, held unchanged; no market quote, APR or actual mortgage compounding convention is reproduced. Loan principal and cash balances remain constant throughout the selected period. No installment, principal repayment, interest capitalization, savings compounding, transaction date, bank balance, tax, interest deduction or payoff horizon is calculated. The entered extra offset fee applies ONCE to the whole selected period and is not automatically prorated when days change. Cost advantage equals alternative loan interest minus separate savings interest, minus offset loan interest and extra fee; positive means lower modeled net financing cost with offset. It is not a cash receipt or portfolio return. Avoided interest at the offset quote alone is not this complete comparison. The source describes an Australian product concept; the hypothetical CAD labels establish no Canadian product availability, tax treatment or local legal rule. Actual access, linkage, full/partial offset and pricing require the product terms.',charts:[
  {id:'offset-account-balances',type:'bar',axisRight:36,title:'Linked cash reduces the interest base while gross loan principal still exists',unit:'money',unitLabel:'CAD balance definitions · separate quantities, not additive pieces',rows:[{label:'Gross loan principal · unchanged',value:i.offsetDebt},{label:'Cash in the linked account',value:i.offsetCashBalance},{label:'Balance charged interest after full offset',value:p.interestBase}],note:'No cash is transferred to principal in this snapshot. The linked account and the loan remain separate. A zero interest base does not mean the gross loan is repaid or that required principal installments disappear. These balances are not pieces of one pie and should not be added as a total.'},
  {id:'offset-account-cost-bridge',type:'waterfall',title:'Reconcile avoided interest with rate differences, forgone savings interest and fees',unit:'money',unitLabel:'CAD cost difference over the selected actual-day period · before tax',rows:[{label:'Interest avoided at the offset-loan quote',value:p.avoided},{label:'Cost from offset quote premium / discount',value:-p.quotePremium},{label:'Separate savings interest forgone',value:-p.separateInterest},{label:'Extra offset fee for this period',value:-i.offsetFee}],totalLabel:'Net cost advantage / disadvantage of offset',note:'The quote-difference row applies the difference between loan rates to gross principal before the offset benefit is credited. It adds value when the offset quote is lower, and subtracts when higher. This decomposition equals the alternative’s loan interest less its savings interest, minus the offset arrangement’s interest and extra fee. Each component enters once.'},
  {id:'offset-account-cash-sensitivity',type:'line',title:'Extra linked cash stops avoiding additional loan interest once it covers the principal',unit:'money',unitLabel:'CAD net period cost advantage of offset · positive is lower modeled cost',xLabel:'Cash in either alternative · CAD',xUnit:'money',series:[{name:'Offset cost advantage after rate difference and fee',rows:cashValues.map(cash=>({x:cash,value:offsetAccountCosts(i,cash).advantage}))}],note:'Each point is an independent constant-balance scenario using the selected loan quotes, savings assumption, period and fee. The exact gross-principal kink and entered cash amount are included. Beyond the loan balance, linked cash avoids no more interest while the separate savings alternative continues earning on all of its cash. The line is not a time path or a recommendation to hold the maximizing amount.'},
  {id:'offset-account-loan-quote-grid',type:'heatmap',signed:true,title:'Compare both loan quotes instead of treating offset interest avoided as the final saving',unit:'money',unitLabel:'CAD net period cost advantage of offset · columns are alternative-loan quotes',columns:['4% alt','5% alt','6% alt','7% alt'],rows:[4,5,6,7].map(rate=>({label:rate+'% offset',values:[4,5,6,7].map(alternative=>offsetAccountCosts(i,i.offsetCashBalance,rate,alternative).advantage)})),note:'Rows replace the offset-loan annual simple quote and columns replace the alternative-loan quote. Gross principal, cash, savings assumption, actual-day count and the extra fee remain selected. Positive is a lower modeled net cost with offset; negative is higher. These invented rate combinations have no assigned likelihood or product availability.'}
 ]};
}
